"// hooks/board-dock.ts",
"var DOCK_MIN_WORK = 1280;",
"var DOCK_MIN_WIDTH = 400;",
"var DOCK_MAX_WIDTH = 560;",
"var dockWidth = (workWidth) => Math.round(Math.min(DOCK_MAX_WIDTH, Math.max(DOCK_MIN_WIDTH, workWidth * 0.25)));",
"var dockPlace = (work) => {",
"  if (!(work.width >= DOCK_MIN_WORK) || !(work.height > 0))",
"    return null;",
"  const width = dockWidth(work.width);",
"  return { x: work.x + work.width - width, y: work.y, width, height: work.height };",
"};",
"var LIMIT = 1e5;",
"var isWhole = (value, min, max) => typeof value === \"number\" && Number.isInteger(value) && value >= min && value <= max;",
"var isPlace = (value) => {",
"  if (value === null || typeof value !== \"object\" || Array.isArray(value))",
"    return false;",
"  const { x, y, width, height } = value;",
"  return isWhole(x, -LIMIT, LIMIT) && isWhole(y, -LIMIT, LIMIT) && isWhole(width, 100, LIMIT) && isWhole(height, 100, LIMIT);",
"};",
"var placeOf = (value) => {",
"  if (!isPlace(value))",
"    return null;",
"  const { x, y, width, height } = value;",
"  return { x, y, width, height };",
"};",
"var windowPath = (progressPath) => `${progressPath.replace(/\\.md$/i, \"\")}-window.json`;",
"var windowPlaceOf = (text) => {",
"  if (text === null || text.trim() === \"\")",
"    return null;",
"  try {",
"    return placeOf(JSON.parse(text));",
"  } catch {",
"    return null;",
"  }",
"};",
"var span = (start, size, otherStart, otherSize) => Math.max(0, Math.min(start + size, otherStart + otherSize) - Math.max(start, otherStart));",
"var isReachable = (place, works) => works.some((work) => span(place.x, place.width, work.x, work.width) >= 100 && span(place.y, 30, work.y, work.height) >= 20);",
"var launchPlace = (remembered, foreground, works) => {",
"  if (remembered !== null && isReachable(remembered, works))",
"    return remembered;",
